import React, { useState, useRef, useEffect, useCallback } from 'react';

function isTouchDevice() {
  return 'ontouchstart' in window || navigator.maxTouchPoints > 0;
}

let activeTooltipHide = null;

export function Tooltip({ children, cost, syns }) {
  const [show, setShow] = useState(false);
  const [position, setPosition] = useState({ top: 0, left: 0 });
  const [visible, setVisible] = useState(false); // controls opacity/visibility after positioning
  const timeoutRef = useRef(null);
  const hideTimeoutRef = useRef(null);
  const touchStartTimeRef = useRef(null);
  const buttonRef = useRef(null);
  const tooltipRef = useRef(null);
  const isTouch = isTouchDevice();
  const hideTooltipRef = useRef(null);

  const LONG_PRESS_DURATION = 500;
  const HIDE_DELAY = 2000;

  // cleanup
  useEffect(() => {
    return () => {
      if (timeoutRef.current) clearTimeout(timeoutRef.current);
      if (hideTimeoutRef.current) clearTimeout(hideTimeoutRef.current);
      if (activeTooltipHide === hideTooltipRef.current) activeTooltipHide = null;
    };
  }, []);

  const updatePosition = useCallback(() => {
    if (!buttonRef.current || !tooltipRef.current) return;
    const buttonRect = buttonRef.current.getBoundingClientRect();
    const tooltipRect = tooltipRef.current.getBoundingClientRect();

    // Position above the button, centered horizontally
    let top = buttonRect.top - tooltipRect.height - 6;
    let left = buttonRect.left + (buttonRect.width / 2) - (tooltipRect.width / 2);

    // Clamp to viewport
    left = Math.max(6, Math.min(left, window.innerWidth - tooltipRect.width - 6));
    if (top < 6) top = buttonRect.bottom + 6;

    setPosition({ top, left });
  }, []);

  const showTooltip = useCallback(() => {
    if (activeTooltipHide && activeTooltipHide !== hideTooltipRef.current) {
      activeTooltipHide(true);
      activeTooltipHide = null;
    }
    activeTooltipHide = hideTooltipRef.current;

    setShow(true);
    setVisible(false); // hidden until positioned
    requestAnimationFrame(() => {
      requestAnimationFrame(() => {
        updatePosition();
        setVisible(true); // now reveal
      });
    });
  }, [updatePosition]);

  const hideTooltip = useCallback((immediate = false) => {
    if (hideTimeoutRef.current) {
      clearTimeout(hideTimeoutRef.current);
      hideTimeoutRef.current = null;
    }
    if (activeTooltipHide === hideTooltipRef.current) activeTooltipHide = null;

    if (immediate) {
      setShow(false);
      setVisible(false);
      if (timeoutRef.current) { clearTimeout(timeoutRef.current); timeoutRef.current = null; }
      touchStartTimeRef.current = null;
    } else {
      hideTimeoutRef.current = setTimeout(() => {
        setShow(false);
        setVisible(false);
        if (timeoutRef.current) { clearTimeout(timeoutRef.current); timeoutRef.current = null; }
        touchStartTimeRef.current = null;
        hideTimeoutRef.current = null;
        if (activeTooltipHide === hideTooltipRef.current) activeTooltipHide = null;
      }, HIDE_DELAY);
    }
  }, []);

  hideTooltipRef.current = hideTooltip;

  const cancelHide = useCallback(() => {
    if (hideTimeoutRef.current) { clearTimeout(hideTimeoutRef.current); hideTimeoutRef.current = null; }
  }, []);

  // Desktop hover
  const handleMouseEnter = () => {
    if (!isTouch) {
      timeoutRef.current = setTimeout(() => showTooltip(), 300);
    }
  };
  const handleMouseLeave = () => {
    if (!isTouch) hideTooltip(false);
  };
  const handleTooltipMouseEnter = () => { if (!isTouch) cancelHide(); };
  const handleTooltipMouseLeave = () => { if (!isTouch) hideTooltip(false); };

  // Mobile touch
  const handleTouchStart = (e) => {
    if (isTouch) {
      touchStartTimeRef.current = Date.now();
      e.preventDefault();
      e.stopPropagation();
      if (timeoutRef.current) clearTimeout(timeoutRef.current);
      timeoutRef.current = setTimeout(() => {
        showTooltip();
        if (navigator.vibrate) navigator.vibrate(10);
      }, LONG_PRESS_DURATION);
    }
  };
  const handleTouchEnd = (e) => {
    if (isTouch) {
      const touchDuration = Date.now() - (touchStartTimeRef.current || 0);
      if (touchDuration < LONG_PRESS_DURATION) {
        hideTooltip();
        if (timeoutRef.current) { clearTimeout(timeoutRef.current); timeoutRef.current = null; }
      } else {
        e.preventDefault();
        e.stopPropagation();
        e.stopImmediatePropagation();
      }
    }
  };
  const handleTouchCancel = () => { if (isTouch) hideTooltip(); };

  // Tap outside to dismiss on mobile
  useEffect(() => {
    if (show && isTouch) {
      const handleTouchOutside = (e) => {
        if (tooltipRef.current && !tooltipRef.current.contains(e.target) &&
            buttonRef.current && !buttonRef.current.contains(e.target)) {
          hideTooltip();
        }
      };
      const timeout = setTimeout(() => {
        document.addEventListener('touchstart', handleTouchOutside);
      }, 100);
      return () => {
        clearTimeout(timeout);
        document.removeEventListener('touchstart', handleTouchOutside);
      };
    }
  }, [show, isTouch, hideTooltip]);

  // Reposition on resize/scroll while shown
  useEffect(() => {
    if (show) {
      const handleResize = () => requestAnimationFrame(() => { updatePosition(); });
      window.addEventListener('resize', handleResize);
      window.addEventListener('scroll', handleResize, true);
      return () => {
        window.removeEventListener('resize', handleResize);
        window.removeEventListener('scroll', handleResize, true);
      };
    }
  }, [show, updatePosition]);

  const childWithHandlers = React.cloneElement(children, {
    ref: (node) => {
      buttonRef.current = node;
      const childRef = children.ref;
      if (childRef) {
        if (typeof childRef === 'function') childRef(node);
        else if (childRef && typeof childRef === 'object') childRef.current = node;
      }
    },
    onMouseEnter: handleMouseEnter,
    onMouseLeave: handleMouseLeave,
    onTouchStart: handleTouchStart,
    onTouchEnd: handleTouchEnd,
    onTouchCancel: handleTouchCancel,
    onContextMenu: (e) => { if (isTouch) e.preventDefault(); },
    style: {
      ...children.props.style,
      WebkitUserSelect: 'none',
      MozUserSelect: 'none',
      msUserSelect: 'none',
      userSelect: 'none',
      WebkitTouchCallout: 'none',
      WebkitTapHighlightColor: 'transparent',
      touchAction: 'none',
      msTouchAction: 'none',
    },
  });

  return (
    <>
      {childWithHandlers}
      {show && (
        <div
          ref={tooltipRef}
          onMouseEnter={handleTooltipMouseEnter}
          onMouseLeave={handleTooltipMouseLeave}
          style={{
            position: 'fixed',
            top: `${position.top}px`,
            left: `${position.left}px`,
            background: 'rgba(0, 0, 0, 0.92)',
            border: '1px solid rgba(152, 201, 255, 0.35)',
            borderRadius: '4px',
            padding: '6px 10px',
            color: '#98c9ff',
            fontSize: '13px',
            fontFamily: 'monospace, Courier, Arial, Helvetica, sans-serif',
            whiteSpace: 'nowrap',
            zIndex: 10001,
            pointerEvents: 'auto',
            boxShadow: '0 2px 8px rgba(0, 0, 0, 0.5)',
            lineHeight: '1.4',
            textAlign: 'left',
            opacity: visible ? 1 : 0,
            transition: 'opacity 0.12s ease',
          }}
        >
          <div>${cost.toLocaleString()}</div>
          <div>{syns} links</div>
        </div>
      )}
    </>
  );
}
